import { Button } from "@/components/ui/Button";
import { MotionReveal } from "@/components/ui/MotionReveal";
import { Accent } from "@/components/ui/SectionHeading";
import { globe } from "@/components/home/globe-data";

/**
 * World-map globe. Colombo and Melbourne are labelled; the other pins are deliberately unlabelled,
 * so the graphic says "we connect to the world" rather than naming offices.
 * The shapes are generated by scripts/generate-globe.mjs.
 */
function Globe() {
  const centre = globe.size / 2;
  return (
    <svg
      viewBox={`0 0 ${globe.size} ${globe.size}`}
      className="mx-auto h-auto w-full max-w-[560px]"
      role="img"
      aria-label="World map globe connecting Sri Lanka and Australia to partners around the world"
    >
      <defs>
        <radialGradient id="globe-sphere" cx="38%" cy="30%" r="78%">
          <stop offset="0%" stopColor="hsl(262 80% 98%)" />
          <stop offset="60%" stopColor="hsl(262 62% 92%)" />
          <stop offset="100%" stopColor="hsl(256 58% 82%)" />
        </radialGradient>
        <linearGradient id="globe-arc" x1="0" x2="1">
          <stop offset="0%" stopColor="hsl(256 72% 52%)" />
          <stop offset="100%" stopColor="hsl(290 56% 49%)" />
        </linearGradient>
        <clipPath id="globe-clip">
          <circle cx={centre} cy={centre} r={globe.radius} />
        </clipPath>
      </defs>

      {/* Soft halo */}
      <circle cx={centre} cy={centre} r={globe.radius + 18} fill="hsl(256 72% 52% / 0.06)" />
      <circle cx={centre} cy={centre} r={globe.radius} fill="url(#globe-sphere)" />

      <g clipPath="url(#globe-clip)">
        <path d={globe.land} fill="hsl(256 46% 62% / 0.5)" stroke="hsl(256 50% 48% / 0.4)" strokeWidth="0.6" strokeLinejoin="round" />
      </g>
      <circle cx={centre} cy={centre} r={globe.radius} fill="none" stroke="hsl(256 50% 60% / 0.35)" strokeWidth="1.2" />

      {/* Connections: the Colombo to Melbourne line is the strongest; the rest show reach beyond Australia. */}
      {globe.arcs.map((arc, index) => (
        <path
          key={index}
          d={arc.d}
          fill="none"
          stroke={arc.primary ? "url(#globe-arc)" : "hsl(256 72% 52% / 0.55)"}
          strokeWidth={arc.primary ? 2.6 : 1.5}
          strokeLinecap="round"
          strokeDasharray={arc.primary ? "7 9" : "4 7"}
          className={arc.primary ? "animate-[dash-flow_1.6s_linear_infinite]" : "animate-[dash-flow_2.6s_linear_infinite]"}
        />
      ))}

      {/* Pins */}
      {globe.pins.map((pin) =>
        "hub" in pin ? (
          <g key={pin.id}>
            <circle cx={pin.x} cy={pin.y} r="15" fill="hsl(256 72% 52% / 0.18)" />
            <circle cx={pin.x} cy={pin.y} r="7" fill={pin.id === "melbourne" ? "hsl(290 56% 49%)" : "hsl(256 72% 52%)"} stroke="white" strokeWidth="2" />
            <text
              x={pin.x + (pin.id === "colombo" ? -14 : 14)}
              y={pin.y + 5}
              textAnchor={pin.id === "colombo" ? "end" : "start"}
              className="fill-ink text-[17px] font-semibold"
              stroke="white"
              strokeWidth="4"
              paintOrder="stroke"
            >
              {pin.label}
            </text>
          </g>
        ) : (
          <circle key={pin.id} cx={pin.x} cy={pin.y} r="4.5" fill="hsl(256 72% 52%)" stroke="white" strokeWidth="1.5" />
        )
      )}
    </svg>
  );
}

export function GlobalConnection() {
  return (
    <section className="relative overflow-hidden bg-white py-20 lg:py-28">
      <div className="container-x grid items-center gap-12 lg:grid-cols-[0.95fr_1.05fr] lg:gap-16">
        <MotionReveal direction="left">
          <div>
            <h2 className="text-4xl font-semibold leading-[1.08] tracking-tight text-ink sm:text-5xl lg:text-6xl">
              Linking <Accent>Lankan</Accent> talent with businesses across Australia and beyond.
            </h2>
            <p className="mt-8 text-lg leading-8 text-muted">
              The idea is pretty simple. Great talent is in Sri Lanka, great businesses are out there, and we help bring the
              two together. Being Australian-based means the roles we create put you directly into teams working with
              businesses across Australia and beyond, giving you international exposure from day one.
            </p>
            <Button href="/about" className="mt-8">
              About Voigue
            </Button>
          </div>
        </MotionReveal>
        <MotionReveal direction="right" delay={0.1}>
          <Globe />
        </MotionReveal>
      </div>
    </section>
  );
}
